// Copies the Portal API spec generated by the backend build into `apis/`.
import { access, copyFile } from 'node:fs/promises'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..')
const source = path.resolve(root, '../devportal-api/openapi/portal-api.json')
const target = path.join(root, 'apis', 'portal-api.json')

try {
  await access(source)
} catch {
  console.error(
    `No se encontró la spec de la Portal API en ${source}.\n` +
      'Clonar devportal-api en la misma carpeta que este repo y correr `dotnet build` ahí para generarla.',
  )
  process.exit(1)
}

await copyFile(source, target)
console.log(`Spec copiada: ${source} -> ${target}`)
